mapper.select:
select * from dm_device


        and  dm_device.name LIKE CONCAT(#{criteria.name},'%')


        and  dm_device.ip LIKE CONCAT(#{criteria.ip},'%')


        and  dm_device.type = #{criteria.type}


        and  dm_device.subtype = #{criteria.subtype}


        and  dm_device.status = #{criteria.status}


        and  dm_device.camera_id = #{criteria.cameraId}


order by id DESC

mapper.update:
UPDATE dm_device SET
serial_no=#{serialNo}, name=#{name}, ip=#{ip}, port=#{port},
type=#{type}, subtype=#{subtype}, status=#{status}, camera_id=#{cameraId}
WHERE id=#{id}
